    81      /* Sends a message over the connection. The message buffer is always freed,
    82       * even if sending fails.
    83       *
    84       * @param connection The connection
    85       * @param buf The message buffer
    86       * @return Returns an error code or UA_STATUSCODE_GOOD. */
    87      UA_StatusCode (*send)(UA_Connection *connection, UA_ByteString *buf);
    88
    89      /* Receive a message from the remote connection
